namespace App;
use Std\Io\{writeStdout,IoError};
let mark:Function(String,Int):Int=function(text:String,value:Int):Int{discard writeStdout(text);value};
let make:Function():Function(Int,Int):Int=function():Function(Int,Int):Int{discard writeStdout("C");function(a:Int,b:Int):Int{a+b}};let main:Function(List<String>):Int=function(args:List<String>):Int{discard args;make()(mark("A",2),mark("B",3))};

short-circuit.source:
namespace App;
use Std\Io\{writeStdout,IoError};
let mark:Function(String,Int):Int=function(text:String,value:Int):Int{discard writeStdout(text);value};
let yes:Function(String):Bool=function(text:String):Bool{discard writeStdout(text);true};let main:Function(List<String>):Int=function(args:List<String>):Int{discard args;let a:Bool=false&&yes("bad");let b:Bool=true||yes("bad");branch when{a||!b=>1,true=>{discard writeStdout("ok");0},else=>{discard writeStdout("bad");2}}};

try-argument.source:
namespace App;
use Std\Io\{writeStdout,IoError};
let mark:Function(String,Int):Int=function(text:String,value:Int):Int{discard writeStdout(text);value};
let pair:Function(Int,Int):Result<Bool,String>=function(a:Int,b:Int):Result<Bool,String>{Result<Bool,String>::Ok(a==b)};let failure:Function():Result<Int,String>=function():Result<Int,String>{discard writeStdout("E");Result<Int,String>::Err("kept"+" error")};let invoke:Function():Result<Bool,String>=function():Result<Bool,String>{pair(try failure(),mark("bad",2))};let main:Function(List<String>):Int=function(args:List<String>):Int{discard args;branch on invoke(){Result<Bool,String>::Ok(value:Bool)=>1,Result<Bool,String>::Err(error:String)=>branch when{error=="kept error"=>0,else=>2}}};

switch-once.source:
namespace App;
use Std\Io\{writeStdout,IoError};
let mark:Function(String,Int):Int=function(text:String,value:Int):Int{discard writeStdout(text);value};
type Choice=sum{No;Yes(String);};let choose:Function():Choice=function():Choice{discard writeStdout("T");Choice::Yes("a"+"b")};let main:Function(List<String>):Int=function(args:List<String>):Int{discard args;branch on choose(){Choice::No=>{discard writeStdout("bad");1},Choice::Yes(text:String)=>{discard writeStdout(text);0}}};
